import{_ as t,o as s,c as l,j as e,a as o}from"./chunks/framework.DdpBa4_E.js";const i="/ReadBooks/assets/image-097.Dl64Be5j.jpg",h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/xialiu-shehui/42-传统的家庭意识依然根深蒂固.md","filePath":"books/xialiu-shehui/42-传统的家庭意识依然根深蒂固.md","lastUpdated":1794732511000}'),r={name:"books/xialiu-shehui/42-传统的家庭意识依然根深蒂固.md"};function n(_,a,d,p,u,c){return s(),l("div",null,[...a[0]||(a[0]=[e("h2",{id:"传统的家庭意识依然根深蒂固",tabindex:"-1"},[o("传统的家庭意识依然根深蒂固 "),e("a",{class:"header-anchor",href:"#传统的家庭意识依然根深蒂固","aria-label":'Permalink to "传统的家庭意识依然根深蒂固"'},"​")],-1),e("p",null,"考察阶层意识与家庭形态的关系则可以看出，无论男性还是女性，一个人独身生活的人阶层意识多为“下流”，其中男性达73.7%，女性达72.7%（见表4-9）。这其中，与父母亲生活在一起的“啃老”男性，这一比例更是高达74.1%，而“啃老”女性阶层意识为“下流”的却只有30.8%，“中流”倒有53.8%。这说明，与男性相比，女性对于“啃老”的自卑感似乎并不如男性那么强烈。",-1),e("p",null,"表4-9　团块次代各种不同家庭形态对阶层意识的影响",-1),e("p",null,[e("img",{src:i,alt:"",loading:"lazy"})],-1),e("p",null,"资料出处：Culture Studies研究所、e-FALCON共同实施的“欲求调查”",-1),e("p",null,"另一方面，凡是已婚的女性无论婚后组成的家庭形态如何，都有约25%的人感觉自己是上流阶层，而男性只有拥有一个孩子、同时妻子是专职家庭主妇的场合，才有27%的人感觉自己是上流阶层。换言之，对女性来说，结婚本身就足以使她们提升自己的阶层意识，而对于男性来说，只有当用自己的工资收入来养活妻儿的时候，方才有一种自己是上流阶层的感觉，虽说是团块次代，但其头脑中的家庭意识却出人意料的陈旧。",-1),e("p",null,"从上表中我们可以得出这样一个结论：男性与女性之间存在一定的收入差距，可以使双方更加容易找到婚姻的另一半，而婚后生育孩子之后，一般来说夫妇双方对生活的满意程度也更加高，这是一个无须讳言的事实。强调男女在所有方面都享有平等，这在政治生活中是完全正确的，但至少对于现阶段的大多数日本人来说，似乎并不符合他们朴素的婚姻观念。",-1)])])}const f=t(r,[["render",n]]);export{h as __pageData,f as default};
